mapper.select:
select mn.*, pp.P_Name as blxwProjectName, si.Sec_Name as blxwSectionName,
con.Con_Name as blxwContractName,
su.U_Name as blxwResponsibleUnitLeaderName, sc.C_Name as blxwResponsibleUnitName,
sd.D_Name as blxwLevelName
from Blxw_Info mn
left join Pre_Project pp on mn.Blxw_Project_Id = pp.P_Id
left join Sec_Info si on mn.Blxw_Section_Id = si.Sec_Id
left join Con_Contract con on mn.Blxw_Contract_Id = con.Con_Id
left join SYS_User su on mn.Blxw_Responsible_Unit_Leader_Id = su.U_Id
left join SYS_Company sc on mn.Blxw_Responsible_Unit_Id = sc.C_Id
left join sys_dictionary sd on mn.Blxw_Level = sd.D_Code and sd.D_ParentID='0a42a0d7-7a5f-4159-a8a5-ce1edef76584'

    
        and mn.Blxw_Number like concat('%'#{params.blxwNumber} ,'%')
    
    
        and mn.Blxw_Project_Id = #{params.blxwProjectId}
    
    
        
            
                and likePname(#{params.blxwProjectName},mn.Blxw_Project_Id)=true
            
            
                and pp.P_Name like concat('%',#{params.blxwProjectName},'%')
            
        
    
    
        and mn.Blxw_Section_Id = #{params.blxwSectionId}
    
    
        and si.Sec_Name like concat('%',#{params.blxwSectionName},'%')
    
    
        and mn.Blxw_Contract_Id = #{params.blxwContractId}
    
    
        and con.Con_Name like concat('%',#{params.blxwContractName},'%')
    
    
        and mn.Blxw_Responsible_Unit_Id = #{params.blxwResponsibleUnitId}
    
    
        and mn.Blxw_Responsible_Unit_Leader_Id = #{params.blxwResponsibleUnitLeaderId}
    
    
        and su.U_Name like concat('%',#{params.blxwResponsibleUnitLeaderName},'%')
    
    
        and sc.C_Name like concat('%',#{params.blxwResponsibleUnitName},'%')
    
    
        
            
                and likeCname(#{params.blxwResponsibleUnitName},mn.Blxw_Responsible_Unit_Id)=true
            
            
                and sc.C_Name like concat('%',#{params.blxwResponsibleUnitName},'%')
            
        
    
    
        and mn.Blxw_State =#{params.blxwState}
    
    
        and mn.Blxw_State =#{params.state}
    
    
        and mn.Blxw_Handle_Type =#{params.blxwHandleType}
    
    
        and mn.close_status =#{params.closeStatus}
    
    
        and mn.Blxw_Rectify_Time >= #{params.nowDate}
    
    
        and mn.Blxw_Level in
        
            #{item}
        
    

order by mn.Create_Time desc

select ni.*,mn.Blxw_Number as blxwNumber, mn.Blxw_Project_Id as blxwProjectId,mn.Blxw_Section_Id as blxwSectionId, mn.Blxw_Contract_Id as blxwContractId, mn.Blxw_Start_Time as blxwStartTime,mn.Blxw_End_Time as blxwEndTime, mn.Blxw_Responsible_Unit_Id as blxwResponsibleUnitId, mn.Blxw_Responsible_Unit_Leader_Id as blxwResponsibleUnitLeaderId,mn.Blxw_Talk_Time as blxwTalkTime, mn.Blxw_Talk_Place as blxwTalkPlace, mn.Blxw_Type_Ids as blxwTypeIds, mn.Blxw_Type_Names as blxwTypeNames, mn.Blxw_Level,mn.Blxw_Deduct_Score as blxwDeductScore, mn.Blxw_Measures as blxwMeasures, mn.Blxw_Handle_Type as blxwHandleType, mn.Blxw_Rectify_Time as blxwRectifyTime, mn.supporting_annex as supportingAnnex, mn.supporting_document as blxwSupportingDocument,mn.is_history as blxwIsHistory, mn.Blxw_Rectify_Require as blxwRectifyRequire, mn.Blxw_State as blxwState, pp.P_Name as blxwProjectName, si.Sec_Name as blxwSectionName, con.Con_Name as blxwContractName, su.U_Name as blxwResponsibleUnitLeaderName, sc.C_Name as blxwResponsibleUnitName from Notice_Info ni left join Blxw_Info mn on mn.id = ni.Source_Id left join Pre_Project pp on mn.Blxw_Project_Id = pp.P_Id left join Sec_Info si on mn.Blxw_Section_Id = si.Sec_Id left join Con_Contract con on mn.Blxw_Contract_Id = con.Con_Id left join SYS_User su on mn.Blxw_Responsible_Unit_Leader_Id = su.U_Id left join SYS_Company sc on mn.Blxw_Responsible_Unit_Id = sc.C_Id
ni.Source_Code = 'blxwInfo'
and mn.Blxw_Number like concat('%',#{params.blxwNumber},'%')
and mn.Blxw_Project_Id = #{params.blxwProjectId}
and likePname(#{params.blxwProjectName},mn.Blxw_Project_Id)=true
and pp.P_Name like concat('%',#{params.blxwProjectName},'%')
and mn.Blxw_Section_Id = #{params.blxwSectionId}
and si.Sec_Name like concat('%',#{params.blxwSectionName},'%')
and mn.Blxw_Contract_Id = #{params.blxwContractId}
and con.Con_Name like concat('%',#{params.blxwContractName},'%')
and mn.Blxw_Responsible_Unit_Id = #{params.blxwResponsibleUnitId}
and mn.Blxw_Responsible_Unit_Leader_Id = #{params.blxwResponsibleUnitLeaderId}
and su.U_Name like concat('%',#{params.blxwResponsibleUnitLeaderName},'%')
and likeCname(#{params.blxwResponsibleUnitName},mn.Blxw_Responsible_Unit_Id)=true
and sc.C_Name like concat('%',#{params.blxwResponsibleUnitName},'%')
and mn.Blxw_State =#{params.blxwState}
and ni.Notice_Info_Code like concat('%',#{params.noticeInfoCode},'%')
order by ni.Create_Time desc

select infoclose.*,mn.Blxw_Number as blxwNumber, mn.Blxw_Project_Id as blxwProjectId,mn.Blxw_Section_Id as blxwSectionId, mn.Blxw_Contract_Id as blxwContractId, mn.Blxw_Start_Time as blxwStartTime,mn.Blxw_End_Time as blxwEndTime, mn.Blxw_Responsible_Unit_Id as blxwResponsibleUnitId, mn.Blxw_Responsible_Unit_Leader_Id as blxwResponsibleUnitLeaderId,mn.Blxw_Talk_Time as blxwTalkTime, mn.Blxw_Talk_Place as blxwTalkPlace, mn.Blxw_Type_Ids as blxwTypeIds, mn.Blxw_Type_Names as blxwTypeNames, mn.Blxw_Level,mn.Blxw_Deduct_Score as blxwDeductScore, mn.Blxw_Measures as blxwMeasures, mn.Blxw_Handle_Type as blxwHandleType, mn.Blxw_Rectify_Time as blxwRectifyTime,mn.close_status as closeStatus, mn.supporting_annex as supportingAnnex, mn.supporting_document as blxwSupportingDocument,mn.is_history as blxwIsHistory, mn.Blxw_Rectify_Require as blxwRectifyRequire, mn.Blxw_State as blxwState, pp.P_Name as blxwProjectName, si.Sec_Name as blxwSectionName, con.Con_Name as blxwContractName, su.U_Name as blxwResponsibleUnitLeaderName, sc.C_Name as blxwResponsibleUnitName from Notice_Info_Close infoclose left join Blxw_Info mn on mn.id = infoclose.Source_Id left join Pre_Project pp on mn.Blxw_Project_Id = pp.P_Id left join Sec_Info si on mn.Blxw_Section_Id = si.Sec_Id left join Con_Contract con on mn.Blxw_Contract_Id = con.Con_Id left join SYS_User su on mn.Blxw_Responsible_Unit_Leader_Id = su.U_Id left join SYS_Company sc on mn.Blxw_Responsible_Unit_Id = sc.C_Id
and mn.Blxw_Number like concat('%',#{params.blxwNumber},'%')
and mn.Blxw_Project_Id = #{params.blxwProjectId}
and likePname(#{params.blxwProjectName},mn.Blxw_Project_Id)=true
and pp.P_Name like concat('%',#{params.blxwProjectName},'%')
and mn.Blxw_Section_Id = #{params.blxwSectionId}
and si.Sec_Name like concat('%',#{params.blxwSectionName},'%')
and mn.Blxw_Contract_Id = #{params.blxwContractId}
and con.Con_Name like concat('%',#{params.blxwContractName},'%')
and mn.Blxw_Responsible_Unit_Id = #{params.blxwResponsibleUnitId}
and mn.Blxw_Responsible_Unit_Leader_Id = #{params.blxwResponsibleUnitLeaderId}
and su.U_Name like concat('%',#{params.blxwResponsibleUnitLeaderName},'%')
and likeCname(#{params.blxwResponsibleUnitName},mn.Blxw_Responsible_Unit_Id)=true
and sc.C_Name like concat('%',#{params.blxwResponsibleUnitName},'%')
and mn.Blxw_State =#{params.blxwState}
and ni.Notice_Info_Code like concat('%',#{params.noticeInfoCode},'%')
order by infoclose.Create_Time desc
